SKILL_DIR="/home/azureuser/projects/skills/tmp/skills/uipath-maestro-flow"
FLOW="/work/output/artifacts/skill-flow-customer-escalation/CustomerEscalation/CustomerEscalation/CustomerEscalation.flow"

# Set classifyUrgency script
python3 "$SKILL_DIR/scripts/flow_edit.py" set-input \
  --flow "$FLOW" \
  --node classifyUrgency \
  --key script \
  --value 'const urgentKeywords = ["urgent", "critical", "asap", "emergency", "escalate", "blocker", "down", "outage", "sev1", "severity 1"];
const email = $vars.newInboxEmail1.output;
const subject = (email.subject || "").toLowerCase();
const body = (email.bodyPreview || "").toLowerCase();
const text = subject + " " + body;
const isUrgent = urgentKeywords.some(function(kw) { return text.indexOf(kw) !== -1; });
return { isUrgent: isUrgent };' \
  && echo "URGENCY_SCRIPT_SET"

SKILL_DIR="/home/azureuser/projects/skills/tmp/skills/uipath-maestro-flow"
FLOW="/work/output/artifacts/skill-flow-customer-escalation/CustomerEscalation/CustomerEscalation/CustomerEscalation.flow"

# Set classifyVip script - VIP rule: domain allow-list
python3 "$SKILL_DIR/scripts/flow_edit.py" set-input \
  --flow "$FLOW" \
  --node classifyVip \
  --key script \
  --value 'const vipDomains = ["enterprise.com", "bigcorp.com", "goldclient.io", "premiumpartner.net", "vipaccount.org"];
const email = $vars.newInboxEmail1.output;
const fromAddress = (email["from.emailAddress.address"] || email.from && email.from.emailAddress && email.from.emailAddress.address || "").toLowerCase();
const senderDomain = fromAddress.split("@")[1] || "";
const isVip = vipDomains.indexOf(senderDomain) !== -1;
return { isVip: isVip, senderEmail: fromAddress };' \
  && echo "VIP_SCRIPT_SET"

SKILL_DIR="/home/azureuser/projects/skills/tmp/skills/uipath-maestro-flow"
FLOW="/work/output/artifacts/skill-flow-customer-escalation/CustomerEscalation/CustomerEscalation/CustomerEscalation.flow"

# Set generateTicket script
python3 "$SKILL_DIR/scripts/flow_edit.py" set-input \
  --flow "$FLOW" \
  --node generateTicket \
  --key script \
  --value 'const email = $vars.newInboxEmail1.output;
const sender = $vars.classifyVip.output.senderEmail || "";
const timestamp = new Date ? new Date().toISOString() : "unknown";
const ticketId = "TKT-" + Math.floor(Math.abs(Math.sin(sender.length + (email.subject || "").length) * 1e9)).toString(36).toUpperCase();
const ticket = {
  ticketId: ticketId,
  status: "Open",
  subject: email.subject || "(no subject)",
  sender: sender,
  body: email.bodyPreview || ""
};
return { ticket: ticket, ticketId: ticketId };' \
  && echo "TICKET_SCRIPT_SET"

